package vn.iotstar.config; import com.cloudinary.Cloudinary; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import java.util.Map; @Configuration public class CloudinaryConfig{@Bean Cloudinary cloudinary(@Value("${cloudinary.cloud-name}")String n,@Value("${cloudinary.api-key}")String k,@Value("${cloudinary.api-secret}")String s){return new Cloudinary(Map.of("cloud_name",n,"api_key",k,"api_secret",s));}}